-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.forget_cards(cards jsonb, reset_counts boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  action uuid := gen_random_uuid();
  card jsonb;
  n integer := 0;
  patch jsonb := jsonb_build_object(
    'phase', 'new', 'interday', false, 'remaining_steps', 0, 'due', null, 'interval', 0,
    'stability', null, 'difficulty', null, 'last_review', null, 'suspended', false, 'buried_until', null);
begin
  if not public.is_allowed_user() then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
  perform public.lock_user_study();
  if reset_counts then
    patch := patch || '{"reps": 0, "lapses": 0}'::jsonb;
  end if;
  for card in select * from jsonb_array_elements(cards) loop
    if public.browse_change_card(action, 'forget', card, now(), patch) then
      n := n + 1;
    end if;
  end loop;
  return n;
end;
$function$;

grant execute on function public.forget_cards(cards jsonb, reset_counts boolean) to authenticated;
grant execute on function public.forget_cards(cards jsonb, reset_counts boolean) to service_role;
